import{_ as a,o as e,c as o,ag as i}from"./chunks/framework.D9ghT4bC.js";const u=JSON.parse('{"title":"国内玩家模组安装指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/UncivCN/Mod-download-in-China.md","filePath":"zh/UncivCN/Mod-download-in-China.md"}'),n={name:"zh/UncivCN/Mod-download-in-China.md"};function s(d,t,r,c,h,p){return e(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="国内玩家模组安装指南" tabindex="-1">国内玩家模组安装指南 <a class="header-anchor" href="#国内玩家模组安装指南" aria-label="Permalink to &quot;国内玩家模组安装指南&quot;">​</a></h1><blockquote><p>作者：UncivCN</p><p>更新日期：以 git 提交时间为准</p></blockquote><h2 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h2><p>Unciv 的模组几乎全部发布在 GitHub 上，游戏内置的模组浏览器也通过 GitHub 的接口搜索、预览和下载模组。而 GitHub 在国内的网络环境下访问不稳定：模组列表经常加载失败，下载经常中断。这导致国内玩家安装模组非常困难。</p><p>UncivCN 内置了<strong>模组下载源切换</strong>功能，专门解决这个问题。</p><h2 id="游戏内解决方案-切换模组下载源" tabindex="-1">游戏内解决方案：切换模组下载源 <a class="header-anchor" href="#游戏内解决方案-切换模组下载源" aria-label="Permalink to &quot;游戏内解决方案：切换模组下载源&quot;">​</a></h2><p>在游戏主菜单依次打开 <strong>选项（Options）→ 高级（Advanced）</strong>，找到 <strong>模组下载源（Mod download source）</strong>：</p><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>GitHub (official)</td><td>默认值，直连 GitHub，国内网络通常不稳定</td></tr><tr><td>gh-proxy.com</td><td>公共 GitHub 加速镜像（实测支持搜索、预览图与下载）</td></tr><tr><td>ghfast.top</td><td>公共 GitHub 加速镜像</td></tr><tr><td>ghproxy.net</td><td>公共 GitHub 加速镜像</td></tr><tr><td>Custom</td><td>自定义加速前缀，需在下方输入框填写</td></tr></tbody></table><p>切换后回到 <strong>模组管理</strong> 页面，点击刷新（重新进入页面即可），模组列表、预览图与下载都会走所选镜像。</p><h3 id="自动引导" tabindex="-1">自动引导 <a class="header-anchor" href="#自动引导" aria-label="Permalink to &quot;自动引导&quot;">​</a></h3><p>如果模组列表加载失败，游戏会检测当前使用的下载源：</p><ul><li>若还是官方源，会弹出确认框询问是否<strong>一键切换到镜像下载源（gh-proxy.com）并自动重试</strong>，点确认即可；</li><li>若已经是镜像源仍失败，会提示前往 选项 → 高级 更换其它镜像。</li></ul><h3 id="自定义前缀" tabindex="-1">自定义前缀 <a class="header-anchor" href="#自定义前缀" aria-label="Permalink to &quot;自定义前缀&quot;">​</a></h3><p>部分玩家可能有自己搭建或更可靠的加速服务。选择 Custom 后，在下方输入框填入加速前缀（例如 <code>https://gh-proxy.com/</code>），点击 Enter 保存。前缀的用法是把 <code>https://github.com/...</code>、<code>https://raw.githubusercontent.com/...</code> 等 GitHub 链接整体拼在加速域名之后，也就是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://你的加速域名/https://github.com/作者/模组仓库/archive/refs/heads/main.zip</span></span></code></pre></div><p>游戏只会对 GitHub 系域名（github.com、raw.githubusercontent.com、avatars.githubusercontent.com、api.github.com 等）添加前缀，其它地址（例如 Gitee 的直接 zip 链接）不受影响。</p><h2 id="手动方式-粘贴加速链接" tabindex="-1">手动方式：粘贴加速链接 <a class="header-anchor" href="#手动方式-粘贴加速链接" aria-label="Permalink to &quot;手动方式：粘贴加速链接&quot;">​</a></h2><p>不切换下载源也可以安装模组。在 模组管理 → 从网络地址获取模组 中，直接粘贴加速后的 zip 链接，例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://gh-proxy.com/https://github.com/作者/模组仓库/archive/refs/heads/main.zip</span></span></code></pre></div><p>Unciv 支持从任意网址直接下载 zip 并解压安装，Gitee 等其它平台的仓库链接同样适用。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>公共加速镜像均为公益服务，可能限速、失效或更换域名。若内置镜像失效，请先尝试其它内置镜像，或自行搜索当前可用的 GitHub 加速服务填入自定义前缀。</p></div>',21)])])}const b=a(n,[["render",s]]);export{u as __pageData,b as default};
